return $input.all().map(({json: item}) => {
  const {decision, runId, summary, overview} = item;
  if (!summary || !overview || !/^[a-zA-Z0-9]+$/.test(runId || '') ||
      summary.outcome !== 'complete' || summary.deliveredReports !== 1 ||
      !/^[0-9a-f]{64}$/.test(summary.reportSha256 || '') ||
      summary.reportSha256 !== overview.reportSha256 ||
      overview.kind !== 'migration-redirect-audit' ||
      !Number.isSafeInteger(overview.mappedUrls) || overview.mappedUrls < 1 ||
      overview.mappedUrls !== overview.fullyTracedUrls ||
      !Number.isSafeInteger(overview.flaggedUrls) || overview.flaggedUrls < 0 ||
      overview.flaggedUrls > overview.mappedUrls ||
      (overview.flaggedUrls === 0 ? 'clean' : 'findings') !== overview.outcome ||
      overview.outputMode !== summary.outputMode) {
    throw new Error('Incomplete or mismatched audit input');
  }
  const preview = summary.outputMode === 'preview';
  const route = preview ? 'DEMO_ONLY' : (overview.flaggedUrls ? 'HOLD_RELEASE' : 'READY_FOR_SIGN_OFF');
  if ((!preview && summary.outputMode !== 'audit') || decision !== route ||
      summary.chargedEvents !== (preview ? 0 : 1) ||
      summary.eventName !== (preview ? null : 'migration-audited')) {
    throw new Error('Review the audit mode, event and upstream decision');
  }
  return {json: {route, runId, mapped: overview.mappedUrls, flagged: overview.flaggedUrls}};
});
